class Solution:
    def intersectionSizeTwo(self, intervals: list[list[int]]) -> int:
        intervals.sort(key=lambda x: (x[1], -x[0]))
        chosen = []
        for start, end in intervals:
            have = 0
            for point in chosen:
                if start <= point <= end:
                    have += 1
            point = end
            while have < 2:
                if point >= start and point not in chosen:
                    chosen.append(point)
                    have += 1
                point -= 1
        return len(chosen)

